"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[37729],{3331:(e,i,a)=>{a.d(i,{R:()=>l,x:()=>o});var r=a(36672);const t={},n=r.createContext(t);function l(e){const i=r.useContext(n);return r.useMemo((function(){return"function"==typeof e?e(i):{...i,...e}}),[i,e])}function o(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:l(e.components),r.createElement(n.Provider,{value:i},e.children)}},34002:(e,i,a)=>{a.r(i),a.d(i,{assets:()=>c,contentTitle:()=>o,default:()=>d,frontMatter:()=>l,metadata:()=>r,toc:()=>u});const r=JSON.parse('{"id":"2023/04/06","title":"2023-04-06","description":"Remembering Bob Lee","source":"@site/i18n/ro/docusaurus-plugin-content-docs/current/2023/04/06.md","sourceDirName":"2023/04","slug":"/2023/04/06","permalink":"/ro/2023/04/06","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/ro/docusaurus-plugin-content-docs//current/2023/04/06.md","tags":[],"version":"current","frontMatter":{"localized_date":"6 aprilie 2023","top_news":"Remembering Bob Lee"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-07","permalink":"/ro/2023/04/07"},"next":{"title":"2023-04-05","permalink":"/ro/2023/04/05"}}');var t=a(23420),n=a(3331);const l={localized_date:"6 aprilie 2023",top_news:"Remembering Bob Lee"},o="2023-04-06",c={},u=[{value:"Remembering Bob Lee",id:"remembering-bob-lee",level:2},{value:"Bob Lee, fostul CTO al Square, a murit dup\u0103 ce a fost \xeenjunghiat \xeen San Francisco",id:"bob-lee-fostul-cto-al-square-a-murit-dup\u0103-ce-a-fost-\xeenjunghiat-\xeen-san-francisco",level:2},{value:"iOS permite operatorilor s\u0103 adauge re\u021bele WiFi la care nu v\u0103 pute\u021bi \xeempiedica s\u0103 v\u0103 al\u0103tura\u021bi",id:"ios-permite-operatorilor-s\u0103-adauge-re\u021bele-wifi-la-care-nu-v\u0103-pute\u021bi-\xeempiedica-s\u0103-v\u0103-al\u0103tura\u021bi",level:2},{value:"Deep Learning Foundations to Stable Diffusion Deep Learning Foundations to Stable Diffusion",id:"deep-learning-foundations-to-stable-diffusion-deep-learning-foundations-to-stable-diffusion",level:2},{value:"CAN Injection: Furtul ma\u0219inilor f\u0103r\u0103 cheie",id:"can-injection-furtul-ma\u0219inilor-f\u0103r\u0103-cheie",level:2},{value:"Inginerii de la Firefox descoper\u0103 un bug al Windows Defender care cauzeaz\u0103 o utilizare ridicat\u0103 a CPU-ului",id:"inginerii-de-la-firefox-descoper\u0103-un-bug-al-windows-defender-care-cauzeaz\u0103-o-utilizare-ridicat\u0103-a-cpu-ului",level:2},{value:"Segment Anything Model (SAM) poate &quot;t\u0103ia&quot; orice obiect dintr-o imagine",id:"segment-anything-model-sam-poate-t\u0103ia-orice-obiect-dintr-o-imagine",level:2},{value:"Cartea alb\u0103 Bitcoin este ascuns\u0103 \xeen fiecare copie de macOS",id:"cartea-alb\u0103-bitcoin-este-ascuns\u0103-\xeen-fiecare-copie-de-macos",level:2},{value:"Fostul CTO al Square, Bob Lee, a fost \xeenjunghiat mortal \xeen centrul ora\u0219ului San Francisco",id:"fostul-cto-al-square-bob-lee-a-fost-\xeenjunghiat-mortal-\xeen-centrul-ora\u0219ului-san-francisco",level:2},{value:"The case for banning children from social media (\xeen englez\u0103)",id:"the-case-for-banning-children-from-social-media-\xeen-englez\u0103",level:2},{value:"Dang va avea \xeen cur\xe2nd 65.535 puncte karma",id:"dang-va-avea-\xeen-cur\xe2nd-65535-puncte-karma",level:2},{value:"Re\u021bele neuronale: De la zero la erou",id:"re\u021bele-neuronale-de-la-zero-la-erou",level:2},{value:"Un truc pentru a ajunge la flux: Las\u0103-\u021bi munca stricat\u0103",id:"un-truc-pentru-a-ajunge-la-flux-las\u0103-\u021bi-munca-stricat\u0103",level:2},{value:"Este RAM \u0219tears\u0103 \xeenainte de a fi utilizat\u0103 \xeentr-un alt container LXC?",id:"este-ram-\u0219tears\u0103-\xeenainte-de-a-fi-utilizat\u0103-\xeentr-un-alt-container-lxc",level:2},{value:"Perspectiv\u0103: BI cu surs\u0103 deschis\u0103 alimentat de WebAssembly",id:"perspectiv\u0103-bi-cu-surs\u0103-deschis\u0103-alimentat-de-webassembly",level:2},{value:"Grid World",id:"grid-world",level:2},{value:"OpenAI Tokenizer",id:"openai-tokenizer",level:2},{value:"Tabloid - Limbajul de programare a titlurilor Clickbait Headline",id:"tabloid---limbajul-de-programare-a-titlurilor-clickbait-headline",level:2},{value:"GPT4 simul\xe2nd un server FTP la ftp.disney.com",id:"gpt4-simul\xe2nd-un-server-ftp-la-ftpdisneycom",level:2},{value:"Utilizarea mmap pentru a face ca LLaMA s\u0103 se \xeencarce mai repede",id:"utilizarea-mmap-pentru-a-face-ca-llama-s\u0103-se-\xeencarce-mai-repede",level:2}];function s(e){const i={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,n.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(i.header,{children:(0,t.jsx)(i.h1,{id:"2023-04-06",children:"2023-04-06"})}),"\n",(0,t.jsx)(i.h2,{id:"remembering-bob-lee",children:"Remembering Bob Lee"}),"\n",(0,t.jsx)(i.p,{children:"Comunitatea tehnologic\u0103 depl\xe2nge pierderea lui Bob Lee, o figur\u0103 cunoscut\u0103 \xeen industrie. Lee a fost un sus\u021bin\u0103tor al Java, dup\u0103 ce a lucrat la Google \u0219i Square, \u0219i era cunoscut pentru munca sa la cadrul de injec\u021bie a dependen\u021belor Guice. El a fost, de asemenea, co-fondatorul Android Alliance, o ini\u021biativ\u0103 menit\u0103 s\u0103 promoveze inova\u021bia \xeen ecosistemul Android. Contribu\u021biile lui Lee la lumea tehnologiei au fost recunoscute pe scar\u0103 larg\u0103, iar colegii \u0219i colegii s\u0103i \xeei vor sim\u021bi lipsa. Mul\u021bi \u0219i-au \xeemp\u0103rt\u0103\u0219it condolean\u021bele pe re\u021belele de socializare, amintindu-\u0219i de Lee ca de un mentor \u0219i un prieten care \u0219i-a f\u0103cut \xeentotdeauna timp pentru ceilal\u021bi. Odihne\u0219te-te \xeen pace, Bob Lee."}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35457341",children:"Discussion Service"}),".\nBob Lee, co-autorul bibliotecilor Guice \u0219i Java, renumit pentru abilit\u0103\u021bile sale tehnice, bun\u0103tatea \u0219i umilin\u021ba sa, a decedat. Moartea sa a l\u0103sat comunitatea tehnologic\u0103 \xeen doliu \u0219i a determinat mul\u021bi oameni s\u0103 \xee\u0219i \xeemp\u0103rt\u0103\u0219easc\u0103 amintirile \u0219i anecdotele despre el. Mo\u0219tenirea de inova\u021bie \u0219i pasiune l\u0103sat\u0103 de Lee i-a inspirat pe mul\u021bi, iar contribu\u021biile sale la industrie vor fi regretate. \xcen timp ce unele comentarii au divagat, majoritatea au \xeemp\u0103rt\u0103\u0219it g\xe2nduri \u0219i experien\u021be pozitive despre Bob."]}),"\n",(0,t.jsx)(i.h2,{id:"bob-lee-fostul-cto-al-square-a-murit-dup\u0103-ce-a-fost-\xeenjunghiat-\xeen-san-francisco",children:"Bob Lee, fostul CTO al Square, a murit dup\u0103 ce a fost \xeenjunghiat \xeen San Francisco"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://www.sfgate.com/bayarea/article/mill-valley-man-killed-sf-stabbing-17878809.php",children:"Original"}),".\nBob Lee, creatorul aplica\u021biei Cash App \xeen calitate de Chief Technology Officer la Square, a fost identificat ca fiind b\u0103rbatul care a fost ucis \xeen San Francisco din cauza unui incident de \xeenjunghiere; evenimentul a \u0219ocat lumea tehnologiei, oamenii reac\u021bion\xe2nd la vestea brusc\u0103. Poli\u021bia nu a efectuat nicio arestare \u0219i nu a f\u0103cut publice informa\u021bii cu privire la posibilii suspec\u021bi. Lee avea 43 de ani, a fost fondatorul Cash App \u0219i lucra ca Chief Product Officer la MobileCoin \xeen momentul mor\u021bii sale."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35448899",children:"Discussion Service"}),".\nFostul director tehnic al Square, Bob Lee, ucis \xeen San Francisco, st\xe2rne\u0219te discu\u021bii despre crim\u0103 \u0219i guvernare. Comentariile acoper\u0103 disparit\u0103\u021bile de bog\u0103\u021bie, lipsa de locuin\u021be, gentrificarea \u0219i poten\u021bialele solu\u021bii. Discu\u021bia ridic\u0103 probleme legate de sistemele politice \u0219i de statisticile nesigure privind criminalitatea din ora\u0219ele americane. Utilizatorii discut\u0103 despre cauzele poten\u021biale ale criminalit\u0103\u021bii, inclusiv migra\u021bia \xeen mas\u0103, inegalitatea bog\u0103\u021biei, sistemele judiciare afectate \u0219i lipsa de reac\u021bie a poli\u021biei. Compararea criminalit\u0103\u021bii \xeentre diferite \u021b\u0103ri sau culturi nu este util\u0103. Problema criminalit\u0103\u021bii este complex\u0103 \u0219i nu este rezultatul unui singur factor."]}),"\n",(0,t.jsx)(i.h2,{id:"ios-permite-operatorilor-s\u0103-adauge-re\u021bele-wifi-la-care-nu-v\u0103-pute\u021bi-\xeempiedica-s\u0103-v\u0103-al\u0103tura\u021bi",children:"iOS permite operatorilor s\u0103 adauge re\u021bele WiFi la care nu v\u0103 pute\u021bi \xeempiedica s\u0103 v\u0103 al\u0103tura\u021bi"}),"\n",(0,t.jsx)(i.p,{children:'Sistemul de operare iOS permite operatorilor s\u0103 adauge re\u021bele WiFi la care utilizatorii nu pot opta s\u0103 nu se al\u0103ture. Aceast\u0103 caracteristic\u0103 provoac\u0103 \xeengrijorare \xeen r\xe2ndul utilizatorilor de iPhone care au planuri de date limitate sau care se tem de confiden\u021bialitate. Func\u021bia este menit\u0103 s\u0103 ajute operatorii de telefonie s\u0103 lanseze hotspoturi WiFi, dar le permite, de asemenea, s\u0103 adauge re\u021bele WiFi publice la care utilizatorii se conecteaz\u0103 f\u0103r\u0103 s\u0103 \u0219tie, put\xe2nd colecta date sensibile. Utilizatorii au op\u021biuni limitate pentru a dezactiva func\u021bia, inclusiv dezactivarea total\u0103 a WiFi sau alegerea de a "Uita aceast\u0103 re\u021bea" de fiecare dat\u0103 c\xe2nd o \xeent\xe2lnesc. Unii utilizatori cer ca Apple s\u0103 adauge mai mult control asupra acestei func\u021bii, \xeen timp ce al\u021bii sugereaz\u0103 utilizarea unui VPN pentru a-\u0219i proteja datele.'}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35447486",children:"Discussion Service"}),".\niOS 16.4 permite operatorilor s\u0103 adauge re\u021bele gestionate la dispozitive, s\u0103 reduc\u0103 costurile de telefonie mobil\u0103 \u0219i s\u0103 \xeempiedice dezactivarea conect\u0103rii automate, f\u0103r\u0103 a exista \xeen prezent o modalitate de a elimina aceste re\u021bele, \xeen afar\u0103 de resetarea set\u0103rilor de re\u021bea. Utilizatorii raporteaz\u0103 c\u0103 T-Mobile fur\u0103 date \u0219i c\u0103 re\u021belele Wingman din timpul zborului nu se dezactiveaz\u0103 \u0219i se declar\u0103 \u0219oca\u021bi de faptul c\u0103 operatorii dicteaz\u0103 conexiunile WiFi f\u0103r\u0103 ca utilizatorul s\u0103 aib\u0103 posibilitatea de a recurge la ele. Urmeaz\u0103 dezbateri cu privire la modul \xeen care se poate ob\u021bine controlul complet al dispozitivului, unii utilizatori recomand\xe2nd GrapheneOS pentru actualiz\u0103ri de securitate. Hotspoturile WiFi ale operatorilor sunt criticate pentru \xeentreruperea conexiunilor la dispozitivele locale, iar unii consider\u0103 c\u0103 aceast\u0103 func\u021bie este util\u0103 \xeen zonele aglomerate."]}),"\n",(0,t.jsx)(i.h2,{id:"deep-learning-foundations-to-stable-diffusion-deep-learning-foundations-to-stable-diffusion",children:"Deep Learning Foundations to Stable Diffusion Deep Learning Foundations to Stable Diffusion"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://course.fast.ai/Lessons/part2.html",children:"Original"}),'.\n"Practical Deep Learning for Coders - Part 2" este un curs format din peste 30 de ore de con\u021binut video care include acoperirea algoritmului Stable Diffusion de la zero, lucr\xe2nd \xeendeaproape cu exper\u021bi de la Stable.ai \u0219i Hugging Face. Cursul ofer\u0103 o acoperire riguroas\u0103 a celor mai recente tehnici \u0219i dep\u0103\u0219e\u0219te chiar \u0219i ceea ce include Stable Diffusion, ceea ce \xeel face un obiectiv de \xeenv\u0103\u021bare excelent din mai multe motive; cu toate acestea, pentru a profita la maximum de acest curs, ar trebui s\u0103 fi\u021bi un practicant de deep learning rezonabil de \xeencrez\u0103tor. De-a lungul cursului, vom explora metodele de difuzie, vom implementa propriile noastre modele de la zero, vom st\u0103p\xe2ni conceptele Python \u0219i PyTorch pentru a ne implementa modelele. Vom acoperi fundamentele de difuzie, optimizatorii de \xeenv\u0103\u021bare profund\u0103, conceptele Python, fundamentele de baz\u0103, generarea de numere pseudo-aleatorii, arhitecturile re\u021belelor neuronale, arhitecturile generative, transformatoarele \u0219i instruirea cu precizie mixt\u0103.']}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35449831",children:"Discussion Service"}),'.\n"Deep Learning Foundations to Stable Diffusion" exploreaz\u0103 modelarea generativ\u0103 modern\u0103, \xeen timp ce unii recomand\u0103 s\u0103 se concentreze pe marketing. Cursul de \xeenv\u0103\u021bare profund\u0103 de la Fast.ai creeaz\u0103 un cadru de programare de la zero \u0219i este recomandat tuturor celor interesa\u021bi. Exist\u0103 o dezbatere \xeen jurul pericolelor poten\u021biale ale inteligen\u021bei artificiale avansate \u0219i a importan\u021bei reglement\u0103rilor \u0219i a considerentelor etice. Comentatorii sugereaz\u0103 interzicerea produc\u021biei de IA, dar nu este o solu\u021bie pe termen lung dac\u0103 nu o fac toate \u021b\u0103rile. Cursul FastAI nu are declara\u021bii cu prejudec\u0103\u021bi politice sau religioase, iar con\u021binutul s\u0103u este considerat de top. Cursul este accesibil oricui are cuno\u0219tin\u021be de baz\u0103 de matematic\u0103 de liceu \u0219i acoper\u0103 concepte avansate.']}),"\n",(0,t.jsx)(i.h2,{id:"can-injection-furtul-ma\u0219inilor-f\u0103r\u0103-cheie",children:"CAN Injection: Furtul ma\u0219inilor f\u0103r\u0103 cheie"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://kentindell.github.io/2023/04/03/can-injection/",children:"Original"}),".\nHo\u021bii de ma\u0219ini folosesc o nou\u0103 tehnic\u0103 numit\u0103 CAN Injection pentru a ocoli sistemele de chei inteligente din ma\u0219inile moderne, exploat\xe2nd vulnerabilit\u0103\u021bile din protocolul de comunica\u021bie CAN bus. Sistemele sofisticate de securitate auto, inclusiv sistemele de imobilizare a motorului, au devenit vulnerabile. Ho\u021bii folosesc un dispozitiv numit CAN Injector pentru a fura ma\u0219inile f\u0103r\u0103 cheie prin injectarea de mesaje false \xeen sistemul de comunicare intern\u0103 al ma\u0219inii. Dispozitivul cost\u0103 10 dolari \u0219i con\u021bine un cip PIC18F, un firmware preprogramat, un transceiver \u0219i un circuit suplimentar. O solu\u021bie rapid\u0103 sau un mesaj criptografic poate \xeenvinge CAN Injector. Ian Haken prezint\u0103 mai multe modalit\u0103\u021bi prin care constructorii de automobile ar putea contribui la securizarea ma\u0219inilor, dar exploatarea criminal\u0103 a tehnicii este larg r\u0103sp\xe2ndit\u0103. Este o problem\u0103 la nivelul \xeentregii industrii care necesit\u0103 o actualizare a software-ului ECU pentru a \xeenvinge ho\u021bii."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35452963",children:"Discussion Service"}),".\nO tehnic\u0103 de furt de ma\u0219ini f\u0103r\u0103 cheie cunoscut\u0103 sub numele de CAN Injection a fost eviden\u021biat\u0103 pe Hacker News. Consumatorii ar trebui s\u0103 fie aten\u021bi la criptarea sau semnarea CAN Bus, deoarece poate limita instrumentele de diagnosticare ale ter\u021bilor, ceea ce spore\u0219te costurile de repara\u021bie. CAN Bus controleaz\u0103 mai multe func\u021bii ale vehiculului, iar produc\u0103torii de vehicule optimizeaz\u0103 costurile f\u0103r\u0103 mil\u0103. Produc\u0103torii de automobile au cerin\u021be legale de a se separa de dealeri, dar unele comentarii critic\u0103 respectarea de c\u0103tre ace\u0219tia a spiritului legii. M\u0103rcile auto premium utilizeaz\u0103 diverse m\u0103suri de securitate pentru a preveni piratarea ma\u0219inilor, inclusiv dispozitive de imobilizare cu protocoale criptografice adecvate pentru a autentifica mesajele de pornire-\xeenchidere \u0219i cadre CAN/FlexRay/Ethernet semnate pentru a preveni falsificarea mesajelor. Ma\u0219inile ieftine sunt vizate, deoarece sunt u\u0219or de furat, \xeen timp ce ma\u0219inile scumpe sunt \u021binta furturilor violente. Exploatarea descris\u0103 \xeen articol ar putea fi aplicat\u0103 la aproape orice vehicul neconectat fabricat \xeen ultimul deceniu. Utilizarea magistralei CAN \xeen sisteme critice, cum ar fi cele din domeniul avia\u021biei \u0219i al automobilelor, se datoreaz\u0103 simplit\u0103\u021bii cablajului \u0219i rentabilit\u0103\u021bii."]}),"\n",(0,t.jsx)(i.h2,{id:"inginerii-de-la-firefox-descoper\u0103-un-bug-al-windows-defender-care-cauzeaz\u0103-o-utilizare-ridicat\u0103-a-cpu-ului",children:"Inginerii de la Firefox descoper\u0103 un bug al Windows Defender care cauzeaz\u0103 o utilizare ridicat\u0103 a CPU-ului"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://bugzilla.mozilla.org/show_bug.cgi?id=1441918#c82",children:"Original"}),".\nN/A (Acest text nu are leg\u0103tur\u0103 cu subiectul)."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35458746",children:"Discussion Service"}),".\nInginerii de la Firefox au descoperit un bug al Windows Defender care cauzeaz\u0103 utilizarea CPU \xeen browserul Mozilla. Microsoft lanseaz\u0103 un patch pentru a remedia acest lucru. Alte produse AV ar putea, de asemenea, s\u0103 cauzeze probleme de utilizare a CPU. Firefox face mai multe apeluri de sistem dec\xe2t Chrome din motive de securitate. O compara\u021bie arat\u0103 c\u0103 Firefox se comport\u0103 mai rapid dec\xe2t Chrome \xeen unele teste. Exper\u021bii discut\u0103 despre limit\u0103rile Defender, sugereaz\u0103 sandboxing \u0219i hardware MFA. Utilizatorii dezbat eficien\u021ba lui Defender fa\u021b\u0103 de software-ul AV de la ter\u021bi. Unii utilizatori raporteaz\u0103 probleme cu Defender care provoac\u0103 acces lent la sistemul de fi\u0219iere."]}),"\n",(0,t.jsx)(i.h2,{id:"segment-anything-model-sam-poate-t\u0103ia-orice-obiect-dintr-o-imagine",children:'Segment Anything Model (SAM) poate "t\u0103ia" orice obiect dintr-o imagine'}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://segment-anything.com/",children:"Original"}),".\nSegment Anything Model (SAM) dezvoltat de Meta AI poate izola orice obiect dintr-o imagine cu o precizie ridicat\u0103. Acesta poate identifica \u0219i segmenta cu succes obiectele, chiar \u0219i atunci c\xe2nd acestea sunt par\u021bial vizibile sau opace. SAM \xeembun\u0103t\u0103\u021be\u0219te modelele dezvoltate anterior, care se bazau pe indicii de localizare sau pe obiecte proeminente. \xcen loc s\u0103 foloseasc\u0103 aceste indicii, SAM aplic\u0103 meta-\xeenv\u0103\u021barea, valorific\xe2nd \xeenv\u0103\u021barea unui model existent, pentru a putea detecta seturi de date mici, p\u0103rtinitoare sau obiecte nev\u0103zute. SAM poate fi utilizat pentru aplica\u021bii practice, cum ar fi editarea imaginilor, precum \u0219i pentru cercetare \xeen domeniul vederii computerizate."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35455566",children:"Discussion Service"}),'.\nSAM de la Meta AI permite generarea de m\u0103\u0219ti \xeen timp real pentru a "t\u0103ia" orice obiect dintr-o imagine. Licen\u021bierea modelului \u0219i capacit\u0103\u021bile impresionante de inferen\u021b\u0103 ar putea s\u0103-l fac\u0103 popular \xeen r\xe2ndul exper\u021bilor \xeen tehnologie. Printre probleme se num\u0103r\u0103 viteza mai mic\u0103 cu modelul RTX 2080ti 11GB \u0219i precizia limitat\u0103 cu obiectele transparente. Unii v\u0103d strategia de lansare a Meta AI ca parte a unui impuls pentru adoptarea AR. Utilizatorii laud\u0103 reducerea costurilor de adnotare a datelor de c\u0103tre SAM, dar \xeei critic\u0103 viteza \u0219i o compar\u0103 cu iOS. Dezvoltarea poate avea, de asemenea, o poten\u021bial\u0103 aplica\u021bie pentru camere de securitate \u0219i integrare AdobeAI.']}),"\n",(0,t.jsx)(i.h2,{id:"cartea-alb\u0103-bitcoin-este-ascuns\u0103-\xeen-fiecare-copie-de-macos",children:"Cartea alb\u0103 Bitcoin este ascuns\u0103 \xeen fiecare copie de macOS"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://waxy.org/2023/04/the-bitcoin-whitepaper-is-hidden-in-every-modern-copy-of-macos/",children:"Original"}),'.\nO copie \xeen format PDF a whitepaper-ului Bitcoin al lui Satoshi Nakamoto a fost descoperit\u0103 \xeen fiecare copie modern\u0103 a macOS \xeencep\xe2nd cu Mojave \xeen 2018 \u0219i poate fi accesat\u0103 printr-un document de prob\u0103 din utilitarul Image Capture. Cartea alb\u0103 este utilizat\u0103 ca document de prob\u0103 pentru un dispozitiv numit "Virtual Scanner II", care este ascuns sau nu este instalat \xeen mod implicit pentru toat\u0103 lumea. De\u0219i motivul includerii sale este \xeenc\u0103 neclar, este posibil s\u0103 fi fost un PDF multipagin\u0103 convenabil \u0219i u\u0219or pentru scopuri de testare. Exist\u0103 foarte pu\u021bine informa\u021bii disponibile online despre Virtual Scanner II sau despre includerea documentului alb \xeen macOS.']}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35461011",children:"Discussion Service"}),".\nCartea alb\u0103 Bitcoin este ascuns\u0103 \xeen fiecare copie macOS din 2019; specula\u021biile \xeenconjoar\u0103 motivul pentru care este inclus\u0103, iar utilizatorii avertizeaz\u0103 \xeempotriva mineritului pe iPhone. Suma hash se potrive\u0219te cu versiunea original\u0103, dar teoriile variaz\u0103 cu privire la motivul pentru care este inclus\u0103. Au ap\u0103rut pl\xe2ngeri cu privire la aprobarea unei scheme Ponzi, dar utilizatorii clarific\u0103 faptul c\u0103 este ascuns\u0103. Este posibil ca Apple s\u0103 o fi inclus\u0103 din comoditate, dar postarea st\xe2rne\u0219te un dialog despre impactul Bitcoin. Utilizatorii comenteaz\u0103 cu privire la imaginea folosit\u0103 \xeentr-un articol, la dimensiunea fi\u0219ierului PDF \u0219i la faptul c\u0103 tehnologia \u0219i-a pierdut hazul artistic."]}),"\n",(0,t.jsx)(i.h2,{id:"fostul-cto-al-square-bob-lee-a-fost-\xeenjunghiat-mortal-\xeen-centrul-ora\u0219ului-san-francisco",children:"Fostul CTO al Square, Bob Lee, a fost \xeenjunghiat mortal \xeen centrul ora\u0219ului San Francisco"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://sfstandard.com/criminal-justice/san-francisco-stabbing-victim-bob-lee-former-cto-square-mobilecoin/",children:"Original"}),".\nFostul CTO al Square, Bob Lee, a fost \xeenjunghiat mortal \xeen Downtown San Francisco, potrivit The Standard. Lee a fost Chief Product Officer al MobileCoin, o companie de criptomonede din San Francisco, \u0219i un membru iubit al comunit\u0103\u021bilor de dezvoltare software \u0219i tehnologie din Bay Area. Poli\u021bia din San Francisco nu a publicat detalii suplimentare sau identitatea victimei \u0219i solicit\u0103 martori oculari \u0219i \xeenregistr\u0103ri video pentru investiga\u021bia lor. San Francisco a \xeenregistrat 12 omucideri p\xe2n\u0103 la data de 2 aprilie, cu dou\u0103 mai multe dec\xe2t \xeen aceea\u0219i perioad\u0103 a anului trecut. The Standard acoper\u0103 subiecte importante, inclusiv probleme de justi\u021bie penal\u0103 din San Francisco, \u0219i ofer\u0103 buletine informative \u0219i o imagine de ansamblu cuprinz\u0103toare a politicii \u0219i culturii din San Francisco."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35452426",children:"Discussion Service"}),".\nFostul CTO al Square, Bob Lee, \xeenjunghiat mortal \xeen San Francisco; comentariile se refer\u0103 la noi detalii."]}),"\n",(0,t.jsx)(i.h2,{id:"the-case-for-banning-children-from-social-media-\xeen-englez\u0103",children:"The case for banning children from social media (\xeen englez\u0103)"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://www.newyorker.com/news/our-columnists/the-case-for-banning-children-from-social-media",children:"Original"}),".\nDezbaterea privind interzicerea accesului copiilor la social media este \xeen curs de desf\u0103\u0219urare din cauza preocup\u0103rilor legate de dependen\u021b\u0103 \u0219i negativitate. Au fost adoptate unele proiecte de lege pentru a restric\u021biona accesul minorilor la site-urile de socializare \u0219i pentru a elimina func\u021biile care creeaz\u0103 dependen\u021b\u0103, dar acest lucru ridic\u0103 implica\u021bii \xeen ceea ce prive\u0219te libert\u0103\u021bile civile \u0219i limiteaz\u0103 accesul la \u0219tiri \u0219i la perspective diferite, pun\xe2nd problema modului \xeen care ar trebui s\u0103 fie tratate mediile sociale. \xcen timp ce instan\u021bele au anulat protec\u021biile online pentru siguran\u021ba copiilor, crearea de mesaje anti-dependen\u021b\u0103 \u0219i de restric\u021bii legale prezint\u0103 poten\u021biale conflicte cu drepturile primului amendament, iar p\u0103rin\u021bii ar putea fi nevoi\u021bi s\u0103 recurg\u0103 la \xeendep\u0103rtarea fizic\u0103 a ecranelor. Protejarea copiilor online este o dezbatere politic\u0103 \u0219i cultural\u0103, l\u0103s\xe2nd pu\u021bin\u0103 \xeencredere \xeen capacitatea guvernului de a reglementa companiile de social media."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35447588",children:"Discussion Service"}),".\nUn articol pledeaz\u0103 pentru interzicerea re\u021belelor sociale pentru tinerii sub 18 ani din cauza poten\u021bialei dependen\u021be asem\u0103n\u0103toare drogurilor; reglementarea acestui tip de con\u021binut prezint\u0103 dificult\u0103\u021bi. O dezbatere cu privire la defini\u021bia \u0219i influen\u021ba reclamelor adresate copiilor ridic\u0103 probleme legate de reglementarea publicit\u0103\u021bii. Sunt ridicate efectele nocive ale social media asupra s\u0103n\u0103t\u0103\u021bii mentale \u0219i dezvolt\u0103rii personale, ceea ce determin\u0103 sugestii de interzicere a social media corporatiste \u0219i a fluxurilor algoritmice. O interdic\u021bie general\u0103 a re\u021belelor sociale nu este considerat\u0103 o solu\u021bie; sunt necesare abord\u0103ri nuan\u021bate. Utilizatorii Discussion Service discut\u0103 modalit\u0103\u021bi eficiente de a limita timpul petrecut \xeen fa\u021ba ecranului \u0219i de a combate efectele negative. Dezbaterea se axeaz\u0103 pe g\u0103sirea unui echilibru \xeentre libertatea individual\u0103 \u0219i responsabilitatea societ\u0103\u021bii. Preocup\u0103rile legate de controlul social media \u0219i de eliberarea de dopamin\u0103 \xeen creier determin\u0103 discu\u021bii privind interzicerea social media alimentate de algoritmi. Fezabilitatea \u0219i poten\u021biala intruziune \xeen via\u021ba privat\u0103 sunt eviden\u021biate ca preocup\u0103ri legate de verific\u0103rile obligatorii de identitate pentru conturile de social media. Nu se discut\u0103 nicio tehnologie nou\u0103 sau lansare major\u0103."]}),"\n",(0,t.jsx)(i.h2,{id:"dang-va-avea-\xeen-cur\xe2nd-65535-puncte-karma",children:"Dang va avea \xeen cur\xe2nd 65.535 puncte karma"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://news.ycombinator.com/user?id=dang",children:"Original"}),".\nUtilizatorul Discussion Service 'dang' se a\u0219teapt\u0103 s\u0103 ajung\u0103 \xeen cur\xe2nd la 65.535 puncte karma, care este limita maxim\u0103 datorit\u0103 utiliz\u0103rii de c\u0103tre sistem a unui num\u0103r \xeentreg cu semn pe 16 bi\u021bi."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35460732",children:"Discussion Service"}),".\nDaniel Gackle, alias Dang, pe cale s\u0103 ajung\u0103 la 65.535 puncte karma. Sec\u021biunea de comentarii este plin\u0103 de laude la adresa muncii lui Dang. Utilizatorii speculeaz\u0103 dac\u0103 karma se va rostogoli \u0219i discut\u0103 despre schimbarea la int pe 32 de bi\u021bi. Stilul de moderare \u0219i implicarea Y Combinator sunt puse la \xeendoial\u0103. Atingerea unei karma ridicate este v\u0103zut\u0103 ca o modalitate de a ar\u0103ta apreciere pentru munca lui Dang. Atingerea unor repere mai \xeenalte de karma permite capacit\u0103\u021bi suplimentare pe Discussion Service, cum ar fi upvoting/downvoting."]}),"\n",(0,t.jsx)(i.h2,{id:"re\u021bele-neuronale-de-la-zero-la-erou",children:"Re\u021bele neuronale: De la zero la erou"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://karpathy.ai/zero-to-hero.html",children:"Original"}),'.\nCursul "Re\u021bele neuronale: Zero to Hero" de Andrej Karpathy \xeenva\u021b\u0103 construirea de re\u021bele neuronale de la zero \xeen cod. Cursul \xeencepe cu elementele de baz\u0103 ale backpropagation \u0219i avanseaz\u0103 p\xe2n\u0103 la re\u021bele neuronale profunde moderne, cum ar fi GPT. Cursul se concentreaz\u0103 pe modelele lingvistice, deoarece acestea reprezint\u0103 un loc excelent pentru a \xeenv\u0103\u021ba \xeenv\u0103\u021barea profund\u0103. Precondi\u021biile prealabile includ o programare solid\u0103 \u0219i un nivel introductiv de matematic\u0103. Cursul include construirea microgradului, a makemore, a unui MLP \u0219i scufundarea \xeen unele dintre elementele interne ale MLP-urilor. De asemenea, sunt abordate \u0219i construirea unui Backprop Ninja \u0219i construirea WaveNet. Cursul culmineaz\u0103 cu construirea GPT. Videoclipurile ofer\u0103 o explica\u021bie pas cu pas \u0219i se concentreaz\u0103 pe dezvoltarea competen\u021bei \u0219i a intui\u021biei \xeen leg\u0103tur\u0103 cu modul \xeen care sunt optimizate re\u021belele neuronale. Cursul recomand\u0103 spectatorilor s\u0103 urm\u0103reasc\u0103 videoclipurile anterioare makemore pentru a se sim\u021bi confortabil cu cadrul de modelare autoregresiv\u0103 a limbajului \u0219i cu elementele de baz\u0103 ale tensorilor \u0219i PyTorch nn.']}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35459031",children:"Discussion Service"}),".\nAndrej Karpathy's 'Neural Networks: Zero to Hero' curs c\xe2\u0219tig\u0103 peste 300 de puncte pe Hacker News \xeen 6 ore. Utilizatorii Discussion Service \xeei laud\u0103 stilul de predare \u0219i recomand\u0103 s\u0103 codifice \xeempreun\u0103 cu el dup\u0103 vizionarea videoclipurilor. Cursul s\u0103u de ML condus de colegi prime\u0219te feedback pozitiv \xeen ciuda faptului c\u0103 nu \xeel men\u021bioneaz\u0103. Sintaxa specific\u0103 Python din videoclipuri ar putea reprezenta o provocare pentru unii utilizatori. O discu\u021bie evalueaz\u0103 accentul pus de curs pe regresia logistic\u0103 \u0219i pe perceptron. Participan\u021bii au considerat cursul u\u0219or de \xeen\u021beles \u0219i recomand\u0103 alte cursuri pentru \xeencep\u0103tori. Unii utilizatori pun la \xeendoial\u0103 cuno\u0219tin\u021bele minime ale dezvoltatorilor web, iar un utilizator are o teorie despre leg\u0103tura dintre ML \u0219i algebra Hopf."]}),"\n",(0,t.jsx)(i.h2,{id:"un-truc-pentru-a-ajunge-la-flux-las\u0103-\u021bi-munca-stricat\u0103",children:"Un truc pentru a ajunge la flux: Las\u0103-\u021bi munca stricat\u0103"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://census.dev/blog/an-on-ramp-to-flow",children:"Original"}),'.\nArticolul discut\u0103 despre dificultatea de a intra \xeentr-o stare de "flux" \xeen sarcinile inginere\u0219ti \u0219i ofer\u0103 un truc pentru a reintra \xeen flux. Autorul sugereaz\u0103 s\u0103 se lase munca \xeentr-o stare care este evident stricat\u0103, dar u\u0219or de reparat, \xeenainte de a se \xeendep\u0103rta. Acest lucru permite un punct de plecare clar atunci c\xe2nd se revine la munc\u0103, cre\xe2nd un impuls \u0219i \xeencredere. Articolul recunoa\u0219te c\u0103 este posibil ca aceast\u0103 abordare s\u0103 nu fie universal\u0103 sau aplicabil\u0103 \xeen cadrul echipelor, dar invit\u0103 la feedback pentru alte trucuri. Exist\u0103, de asemenea, o scurt\u0103 men\u021biune despre Census Engineering \u0219i despre oportunit\u0103\u021bile de angajare.']}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35456059",children:"Discussion Service"}),'.\nUtilizatorii Discussion Service \xeemp\u0103rt\u0103\u0219esc sfaturi pentru a ajunge la starea de flux l\u0103s\xe2nd munca neterminat\u0103, inclusiv metoda "parcheaz\u0103 cu fa\u021ba la vale". Un director de inginerie a implementat l\u0103sarea lucrului p\xe2n\u0103 la ora 18:00 pentru a evita epuizarea, dar a pus cap\u0103t acestei metode din cauza prezenteismului. Utilizatorii discut\u0103 despre beneficiile \u0219i riscurile unor reguli stricte de sincronizare \u0219i despre schimbarea culturii de lucru. Unii \xeemp\u0103rt\u0103\u0219esc sfaturi de productivitate, cum ar fi scrierea pa\u0219ilor urm\u0103tori \u0219i practicarea TDD. L\u0103sarea codului \xeentr-o stare "stricat\u0103" poate ajuta la reluarea mai t\xe2rziu, dar are rezultate mixte.']}),"\n",(0,t.jsx)(i.h2,{id:"este-ram-\u0219tears\u0103-\xeenainte-de-a-fi-utilizat\u0103-\xeentr-un-alt-container-lxc",children:"Este RAM \u0219tears\u0103 \xeenainte de a fi utilizat\u0103 \xeentr-un alt container LXC?"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://security.stackexchange.com/questions/269507/is-ram-wiped-before-use-in-another-lxc-container",children:"Original"}),".\nO postare pe Information Security Stack Exchange \xeentreab\u0103 dac\u0103 memoria RAM este \u0219tears\u0103 \xeenainte de a fi utilizat\u0103 \xeentr-un alt container LXC, ceea ce a dus la o discu\u021bie despre supraprovizionarea RAM \xeen LXC, un utilizator coment\xe2nd c\u0103 memoria alocat\u0103 unui proces anterior \xeentr-un container este \u0219tears\u0103. O postare pe Hacker News aprofundeaz\u0103, discut\xe2nd despre bibliotecile partajate \u0219i despre protec\u021bia spa\u021biilor de nume de utilizator, iar un r\u0103spuns clarific\u0103 faptul c\u0103 paginile sunt \u0219terse \xeenainte de alocare, supraaprovizionarea nu provoac\u0103 partajarea, iar memoria LXC este alocat\u0103 proceselor prin intermediul spa\u021biilor de nume, dar procesele sunt separate de resursele gazd\u0103. \xcen cele din urm\u0103, se men\u021bioneaz\u0103 c\u0103 gestionarea memoriei bazat\u0103 pe glibc nu implic\u0103 cur\u0103\u021barea \u0219i c\u0103 paginile libere pot con\u021bine date."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35451863",children:"Discussion Service"}),".\nUtilizatorii de pe Hacker News au discutat despre eficien\u021ba \u0219i necesitatea reducerii automate la zero a memoriei \xeen Linux, unii suger\xe2nd metode alternative pentru cur\u0103\u021barea memoriei nefolosite. Un utilizator a subliniat faptul c\u0103 problema const\u0103 \xeen proiectarea apelului de sistem fork() din UNIX, iar multe software-uri cu utilizare intensiv\u0103 a memoriei \xeenc\u0103 se lupt\u0103 cu problemele OOM. Alte comentarii discut\u0103 despre diferen\u021bele dintre alocarea de memorie overcommit \u0219i non-overcommit \xeen Linux \u0219i despre importan\u021ba stabilirii unor limite. Articolul ofer\u0103 perspective nuan\u021bate asupra aloc\u0103rii de memorie \xeen Linux \u0219i se adreseaz\u0103 exper\u021bilor \xeen domeniu."]}),"\n",(0,t.jsx)(i.h2,{id:"perspectiv\u0103-bi-cu-surs\u0103-deschis\u0103-alimentat-de-webassembly",children:"Perspectiv\u0103: BI cu surs\u0103 deschis\u0103 alimentat de WebAssembly"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://perspective.finos.org/",children:"Original"}),".\nPerspective este o component\u0103 interactiv\u0103 de analiz\u0103 \u0219i vizualizare a datelor, conceput\u0103 pentru fluxuri \u0219i seturi mari de date, cu rapoarte, tablouri de bord \u0219i notebook-uri configurabile. Dispune de un motor de interogare \xeen flux eficient din punct de vedere al memoriei \xeen C++ \u0219i Python \u0219i de o interfa\u021b\u0103 de utilizator \xeempachetat\u0103 ca un element personalizat alimentat de WebAssembly sau WebSocket. UI include tablouri de bord interactive care pot fi integrate \xeen orice cadru de aplica\u021bii web. Perspective.js se bazeaz\u0103 pe WebAssembly \u0219i Apache Arrow pentru o performan\u021b\u0103 asem\u0103n\u0103toare cu cea a unui desktop \xeen browser. PerspectivePython implementeaz\u0103 API-ul Perspective direct \xeen Python pentru cercetare sau produc\u021bie. Exist\u0103 widget-uri virtualizate \u0219i scalabile, iar proiectul este disponibil pe GitHub cu ghiduri pentru utilizator \u0219i programator."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35455850",children:"Discussion Service"}),".\nInstrumentul de BI cu surs\u0103 deschis\u0103 Perspective, alimentat de WebAssembly, l\u0103udat pentru func\u021bionalitatea puternic\u0103, \xeen ciuda problemelor de performan\u021b\u0103: printre solu\u021biile sugerate se num\u0103r\u0103 utilizarea unei op\u021biuni mai u\u0219oare. Creatorii Perspective lucreaz\u0103 la \xeembun\u0103t\u0103\u021birea performan\u021bei \u0219i a compatibilit\u0103\u021bii cu dispozitivele mobile. Au fost exprimate unele \xeengrijor\u0103ri cu privire la compatibilitatea cu Firefox \u0219i la accesibilitate/designul prietenos f\u0103r\u0103 tastatur\u0103. Au fost discutate limit\u0103rile Sciter, iar bibliotecile Tauri sunt considerate poten\u021bial utile. Sunt necesare \xeembun\u0103t\u0103\u021biri ale performan\u021bei pentru proiectul Perspective."]}),"\n",(0,t.jsx)(i.h2,{id:"grid-world",children:"Grid World"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://alex.miller.garden/grid-world/",children:"Original"}),'.\n"Grid World" a lui Alexander Miller exploreaz\u0103 rolul grilelor \xeen via\u021ba sa din copil\u0103rie p\xe2n\u0103 la v\xe2rsta adult\u0103, inclusiv impactul acestora \xeen tehnologie, art\u0103 \u0219i naviga\u021bie. Articolul abordeaz\u0103 puterea pe care o au grilele \xeen cartografierea \u0219i controlul spa\u021biului, a\u0219a cum se vede \xeen jocuri precum Battleship \u0219i Chess. Grila devine un nod central care leag\u0103 experien\u021bele personale ale lui Miller, ar\u0103t\xe2nd modul \xeen care aceasta devine o parte din via\u021ba noastr\u0103. Miller a creat grila pentru The HTML Review \xeen 2023.']}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35455770",children:"Discussion Service"}),".\nUtilizatorii Discussion Service sunt fascina\u021bi de m\u0103iestria \u0219i m\u0103iestria excep\u021bional\u0103 a Grid World \xeen designul \u0219i dezvoltarea web \u0219i de impactul s\u0103u asupra percep\u021biei. Articolul exploreaz\u0103 sub\xeen\u021belesul grilei fa\u021b\u0103 de amintirile noastre \u0219i fa\u021b\u0103 de lume, cu imagini pixel art \xeenso\u021bitoare. Comentariile remarc\u0103 leg\u0103tura cu neuro\u0219tiin\u021ba cu celulele grilei, ridic\xe2nd \xeen acela\u0219i timp critici privind ra\u021bionalizarea \u0219i p\u0103tura grilei asupra naturii. Un utilizator consider\u0103 c\u0103 este dificil s\u0103 perfec\u021bioneze aspectele de design vizual ale proiectului s\u0103u personal. Utilizatorii discut\u0103 modelele de gril\u0103 din Queens \u0219i istoria din spatele modelelor de gril\u0103. Un utilizator Discussion Service \xeemp\u0103rt\u0103\u0219e\u0219te informa\u021bii despre conformitatea re\u021belei de str\u0103zi din New York. Un decor \xeen form\u0103 de mas\u0103 genereaz\u0103 s\u0103li de dezordine slab luminate \xeen timp ce evolueaz\u0103 \xeen timp, construit cu javascript simplu, f\u0103r\u0103 biblioteci pentru un exerci\u021biu tehnic distractiv."]}),"\n",(0,t.jsx)(i.h2,{id:"openai-tokenizer",children:"OpenAI Tokenizer"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://platform.openai.com/tokenizer",children:"Original"}),".\nAPI-ul OpenAI este o tehnologie care necesit\u0103 activarea JavaScript."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35453400",children:"Discussion Service"}),".\nOpenAI a lansat un nou tokenizer pentru a \xeen\u021belege mai bine modelele GPT. Tokenizatorul \xeemparte textul \xeen unit\u0103\u021bi de subcuvinte pentru o procesare eficient\u0103, dar acestea nu au un \xeen\u021beles inerent. Utilizatorii Discussion Service discut\u0103 despre limit\u0103rile instrumentului, cum ar fi gruparea bazat\u0103 pe spa\u021bii \u0219i tratamentele de capitalizare. Codific\u0103rile create cu ajutorul codific\u0103rii prin perechi de octe\u021bi nu sunt adesea potrivite pentru limbile subreprezentate. OpenAI percepe o tax\u0103 per token datorit\u0103 func\u021bion\u0103rii modelului pe baz\u0103 de token."]}),"\n",(0,t.jsx)(i.h2,{id:"tabloid---limbajul-de-programare-a-titlurilor-clickbait-headline",children:"Tabloid - Limbajul de programare a titlurilor Clickbait Headline"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://tabloid-thesephist.vercel.app/",children:"Original"}),".\nTabloid este un nou limbaj de programare creat pentru a genera titluri ridicole \u0219i demne de a fi accesate, asem\u0103n\u0103toare cu cele din tabloide. Limbajul folose\u0219te o combina\u021bie de procesare a limbajului natural, \xeenv\u0103\u021bare automat\u0103 \u0219i crowd-sourcing pentru a crea titluri cu modele lingvistice de tip clickbaity. Este un limbaj amuzant \u0219i distractiv, care nu serve\u0219te niciunui scop real, dar este un exemplu excelent al modului \xeen care programarea poate fi at\xe2t util\u0103, c\xe2t \u0219i amuzant\u0103. Creatorul lui Tabloid inten\u021bioneaz\u0103 s\u0103 \xeel foloseasc\u0103 pentru a crea o platform\u0103 care s\u0103 permit\u0103 oricui s\u0103 creeze titluri de tip clickbait. Utilizatorii Discussion Service consider\u0103 acest instrument interesant \u0219i un mod util de a \xeen\u021belege procesarea limbajului natural."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35447580",children:"Discussion Service"}),'.\nUn proiect recent de pe Hacker News numit Tabloid - The Clickbait Headline Programming Language (Limbajul de programare a titlurilor Clickbait). Proiectul este fascinant, scris de un autor care pretinde c\u0103 a scris alte limbaje care sunt, f\u0103r\u0103 \xeendoial\u0103, mai utile. Un utilizator Discussion Service a postat un program \xeen Tabloid care ia cinci numere \u0219i returneaz\u0103 produsul primelor trei numere plus produsul ultimelor dou\u0103. Autorul este o persoan\u0103 care a livrat multe proiecte interesante, folosind chiar \u0219i Oak pentru a construi o serie de infrastructuri software personale, printre altele. Un alt utilizator Discussion Service a comentat c\u0103 a scrie totul de la zero este cel mai viabil pentru dezvoltatorii solitari, dar nu \u0219i pentru echipe, unde este mai bine s\u0103 se mearg\u0103 pe "plictisitor".']}),"\n",(0,t.jsx)(i.h2,{id:"gpt4-simul\xe2nd-un-server-ftp-la-ftpdisneycom",children:"GPT4 simul\xe2nd un server FTP la ftp.disney.com"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://www.filestash.app/2023/04/01/chat-gpt-acting-as-a-ftp-server/",children:"Original"}),".\nChat GPT-4 este priceput la simularea unui server FTP pentru Disney, folosind instrumentul de baz\u0103 ftp cli \u0219i venind prompturi pentru a executa comenzi a\u0219a cum ar face un utilizator real. Serverul simulat include con\u021binut exclusiv Disney \xeen dosare precum filme, coloane sonore \u0219i imagini de fundal, iar GPT-4 se dovede\u0219te capabil s\u0103 navigheze \xeen sistemele de fi\u0219iere locale \u0219i la distan\u021b\u0103. Noua tehnologie se comport\u0103 bine, dep\u0103\u0219ind a\u0219tept\u0103rile \u0219i demonstr\xe2ndu-\u0219i capacitatea de a crea con\u021binut atractiv pentru pasiona\u021bii Disney. Articolul face aluzie la viitoarele utiliz\u0103ri ale GPT-4 \xeen plug-in-uri de interpretare a codului care permit accesul la servere inventate de la clien\u021bii FTP."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35450315",children:"Discussion Service"}),'.\nUn articol de pe Hacker News vorbe\u0219te despre GPT4 care simuleaz\u0103 un server FTP la ftp.disney.com. Utilizatorii dezbat dac\u0103 acest lucru poate fi considerat sau nu "halucinant", \xeen ciuda poten\u021bialului de simulare sau "halucina\u021bie" al AI. Acurate\u021bea r\u0103spunsurilor generate de AI \u0219i percep\u021bia acestor rezultate ca fiind "halucina\u021bii" sunt, de asemenea, puncte de discu\u021bie. Alte subiecte discutate includ: poten\u021bialul ca filmele sau emisiunile TV autogenerate s\u0103 fie lipsite de valoare, rolul spa\u021biului latent \u0219i al limbajului \xeen LLM-uri, impactul tehnologiei asupra societ\u0103\u021bii \u0219i limit\u0103rile capacit\u0103\u021bilor actuale ale AI. Unii utilizatori avertizeaz\u0103 \xeempotriva suprainterpret\u0103rii capacit\u0103\u021bilor AI \u0219i remarc\u0103 faptul c\u0103 limit\u0103rile acesteia sunt adesea trecute cu vederea.']}),"\n",(0,t.jsx)(i.h2,{id:"utilizarea-mmap-pentru-a-face-ca-llama-s\u0103-se-\xeencarce-mai-repede",children:"Utilizarea mmap pentru a face ca LLaMA s\u0103 se \xeencarce mai repede"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://justine.lol/mmap/",children:"Original"}),".\nLLaMA folose\u0219te mmap() pentru a \xeenc\u0103rca modelele de 100 de ori mai repede, cre\u0219te stabilitatea RAM \u0219i permite rularea simultan\u0103 a mai multor procese. Utilizatorii Linux ob\u021bin o \xeembun\u0103t\u0103\u021bire de 100x, \xeen timp ce Windows \u0219i MacOS ob\u021bin o \xeembun\u0103t\u0103\u021bire de 10x. Noul \xeenc\u0103rc\u0103tor mmap() este acum disponibil pe GitHub sub licen\u021b\u0103 MIT. Colaboratorul anonim @Slaren a ad\u0103ugat suportul mmap() la LLaMA-7B, permi\u021b\xe2nd timpi de \xeenc\u0103rcare instantanee f\u0103r\u0103 schimbarea formatului de fi\u0219ier. Noul format de fi\u0219ier aliniaz\u0103 tensorii pe o limit\u0103 de 32 de octe\u021bi. Postarea exploreaz\u0103 poten\u021bialele \xeembun\u0103t\u0103\u021biri \xeen utilizarea discului \u0219i \xeentreruperea performan\u021bei. Justine Tunney scrie despre Twitter \u0219i Github \xeen utilit\u0103\u021bi standard, destinate exper\u021bilor din domeniu. Este clar\u0103 \u0219i concis\u0103, f\u0103r\u0103 prejudec\u0103\u021bi sau declara\u021bii politice sau religioase. Un utilizator Discussion Service comenteaz\u0103 c\u0103 postul lui Tunney este o resurs\u0103 excelent\u0103 pentru \xeenv\u0103\u021bare."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35455930",children:"Discussion Service"}),".\nUtilizarea mmap pentru a face ca LLaMA s\u0103 se \xeencarce mai repede este principalul obiectiv al articolului, \xeen ciuda dramatismului \xeen jurul atribuirii \u0219i a problemelor tehnice din sec\u021biunea de comentarii. Sunt discutate beneficiile \u0219i dezavantajele lui mmap, precum \u0219i meritele tehnice ale LLaMA.cpp de la Facebook. Utilizatorii discut\u0103 despre utilitatea modific\u0103rilor aduse de LLaMA \u0219i despre avantajele \u0219i dezavantajele diverselor caracteristici, oferind informa\u021bii valoroase pentru cititorii cunosc\u0103tori de tehnologie interesa\u021bi s\u0103 afle mai multe despre AI \u0219i implementarea modelelor. Postarea eviden\u021biaz\u0103 o abordare a unei probleme prin ingineria sistemelor \u0219i o tendin\u021b\u0103 care implic\u0103 cod proprietar \xeen biblioteci, gener\xe2nd discu\u021bii despre utilizarea Huge Pages \u0219i dificultatea de a rezolva blocajele IO. \xcembun\u0103t\u0103\u021birea revolu\u021bionar\u0103 a performan\u021belor cu ajutorul mmap a atras aten\u021bia exper\u021bilor din domeniu."]})]})}function d(e={}){const{wrapper:i}={...(0,n.R)(),...e.components};return i?(0,t.jsx)(i,{...e,children:(0,t.jsx)(s,{...e})}):s(e)}}}]);